"""Actual existing domain registries, offline command-center export and verification."""
import json,os,pathlib,subprocess
from hub.mission_control import export,verify
from hub.collaboration import Collaboration
root=pathlib.Path(os.environ["RUNNER_TEMP"])
sha=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
# Exactly eight private source registries, all generated by preceding public synthetic smoke steps.
bindings=[("missions",root/"mission-state"),("collaboration",root/"collaboration-state"),
          ("research",root/"racecraft-research-state"),("graphics",root/"advanced-graphics-state"),
          ("performance",root/"benchmark-state"),("development",root/"code-state"),
          ("knowledge",root/"knowledge-state"),("infrastructure",root/"health-state")]
# Add a real unresolved proposal through existing API, never fake registry rows.
c=Collaboration(root/"collaboration-state")
p=json.loads((root/"hub-smoke/collaboration/report.json").read_text())["collaboration"]
req=p["plan"]["request"];roles=p["plan"]["participants"]
pending=c.propose(req,roles,{r:[] for r in roles})
before=[(path/"registry.sqlite3").read_bytes() for _,path in bindings]
out=root/"hub-smoke/mission-control"
s=export(bindings,out)
assert s["registries"]==8 and not s["live"] and not s["execution_authorized"]
assert all(x["records"]>0 for x in s["groups"].values()),s["groups"]
matches=[x for x in s["recent_queue"] if x["id"]==pending["id"]]
assert len(matches)==1 and matches[0]["priority"]=="review" and matches[0]["outcome"] is None,matches
assert verify(out)["status"]=="PASS"
assert before==[(path/"registry.sqlite3").read_bytes() for _,path in bindings]
print("REAL_MISSION_CONTROL_PASS",sha,s["source_sha256"],s["registries"],len(s["groups"]))
